//! Every GraphQL document the Shopify provider sends is valid against
//! Shopify's published Admin GraphQL schema for API version 2026-10.
//!
//! The schema is `tests/fixtures/shopify/schema-2026-10.pruned.graphql`,
//! generated by `scripts/shopify-schema-prune.py` from Shopify's public
//! introspection endpoint <https://shopify.dev/admin-graphql-direct-proxy/2026-10>.
//! Re-run the script after adding or changing a document.

use apollo_compiler::{ExecutableDocument, Schema};
use marketplace_service::connectors::providers::shopify::client::API_VERSION;
use marketplace_service::connectors::providers::shopify::documents;

const SCHEMA: &str = include_str!("fixtures/shopify/schema-2026-10.pruned.graphql");

fn schema() -> apollo_compiler::validation::Valid<Schema> {
    Schema::parse_and_validate(SCHEMA, "schema-2026-10.pruned.graphql")
        .unwrap_or_else(|errors| panic!("the pruned schema is invalid:\n{errors}"))
}

#[test]
fn the_schema_fixture_is_the_pinned_version_and_cites_its_source() {
    assert_eq!(API_VERSION, "2026-10");
    assert!(SCHEMA.contains("API version 2026-10"));
    assert!(SCHEMA.contains("https://shopify.dev/admin-graphql-direct-proxy/2026-10"));
}

#[test]
fn every_document_is_valid_against_the_published_schema() {
    let schema = schema();
    for (name, document) in documents::ALL {
        let text = document.replace("{{KEY}}", "00000000-0000-8000-8000-000000000000");
        ExecutableDocument::parse_and_validate(&schema, text, format!("{name}.graphql"))
            .unwrap_or_else(|errors| {
                panic!("{name}.graphql is invalid for {API_VERSION}:\n{errors}")
            });
    }
}

#[test]
fn no_document_file_escapes_validation() {
    let directory = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("src/connectors/providers/shopify/graphql");
    let mut on_disk: Vec<String> = std::fs::read_dir(directory)
        .expect("graphql directory")
        .map(|entry| {
            entry
                .expect("entry")
                .file_name()
                .to_string_lossy()
                .trim_end_matches(".graphql")
                .to_string()
        })
        .collect();
    on_disk.sort();
    let mut listed: Vec<String> = documents::ALL
        .iter()
        .map(|(name, _)| name.to_string())
        .collect();
    listed.sort();
    assert_eq!(on_disk, listed, "every .graphql file is in documents::ALL");
}

#[test]
fn the_validator_does_reject_a_document_the_schema_does_not_allow() {
    let schema = schema();
    for bad in [
        "query { shop { noSuchField } }",
        "mutation { orderCancel(orderId: \"gid://shopify/Order/1\") { job { id } } }",
        "query { products(first: 1) { nodes { id title nonsense } } }",
    ] {
        assert!(
            ExecutableDocument::parse_and_validate(&schema, bad, "bad.graphql").is_err(),
            "{bad}"
        );
    }
}
